			$retval = null;

			$failureMap = array();


			if (($retval = Tbrh002FichaPeer::doValidate($this, $columns)) !== true) {
				$failureMap = array_merge($failureMap, $retval);
			}


				if ($this->collTbrh007HistorialCargos !== null) {
